/**
 * SPARQL-level edge cases for the set-returning {@code arrf:} magic properties against a {@link MemoryStore}, plus the
 * family-wide clause-position and unbound-argument cases of the scalar {@code jsonf:}/{@code arrf:} functions.
 */
public class MagicPropertyEdgeCaseSparqlTest {

	private static final String PREFIXES = """
			PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
			PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
			PREFIX jsonf: <http://rdf4j.org/function/json#>
			PREFIX arrf: <http://rdf4j.org/function/array#>
			PREFIX ex: <http://example.org/>
			""";

	private static final String DATA = """
			@prefix ex: <http://example.org/> .
			@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
			ex:s1 ex:arr "[1,2]"^^rdf:JSON ; ex:name "one" .
			ex:s2 ex:arr "[3]"^^rdf:JSON ; ex:name "two" .
			ex:s3 ex:name "three" .
			ex:s4 ex:arr "\\"scalar\\""^^rdf:JSON .
			""";

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI EX_ARR = VF.createIRI("http://example.org/arr");
	private static final String UNNEST = "http://rdf4j.org/function/array#unnest";

	private SailRepository repository;

	@BeforeEach
	void setUp() throws Exception {
		repository = new SailRepository(new MemoryStore());
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(DATA), "", RDFFormat.TURTLE);
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private List<BindingSet> evaluate(String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			return new ArrayList<>(QueryResults.asList(result));
		}
	}

	/** Rows as comma-separated string values of the named variables, "UNBOUND" for a missing binding. */
	private List<String> rows(String query, String... names) {
		List<String> rows = new ArrayList<>();
		for (BindingSet row : evaluate(query)) {
			List<String> columns = new ArrayList<>();
			for (String name : names) {
				columns.add(row.hasBinding(name) ? row.getValue(name).stringValue() : "UNBOUND");
			}
			rows.add(String.join(",", columns));
		}
		return rows;
	}

	private String explain(String query, Explanation.Level level) {
		try (RepositoryConnection conn = repository.getConnection()) {
			TupleQuery tupleQuery = conn.prepareTupleQuery(PREFIXES + query);
			return tupleQuery.explain(level).toString();
		}
	}

	private static int count(String text, String needle) {
		int count = 0;
		for (int i = text.indexOf(needle); i >= 0; i = text.indexOf(needle, i + needle.length())) {
			count++;
		}
		return count;
	}

	// ------------------------------------------------------------------ subject and object binding states

	@Test
	void unboundSubjectYieldsNoRowsForThatSolutionAndTheQueryContinues() {
		assertThat(rows("SELECT ?a ?x WHERE { VALUES ?a { '[1,2]'^^rdf:JSON UNDEF '[3]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x } ORDER BY ?x", "a", "x"))
						.containsExactly("[1,2],1", "[1,2],2", "[3],3");
		// an entirely unbound subject (no producer at all) gives an empty result, not an error
		assertThat(rows("SELECT ?x WHERE { ?a arrf:unnest ?x }", "x")).isEmpty();
	}

	@Test
	void nonArraySubjectYieldsNoRows() {
		// invalid JSON text, a non-string literal, an IRI, JSON scalars and malformed rdf:JSON all contribute nothing;
		// only the array produces rows and the query is not aborted
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { 'abc' 5 <urn:x> '\"s\"'^^rdf:JSON 'true'^^rdf:JSON"
				+ " 'null'^^rdf:JSON '{bad'^^rdf:JSON '[1]'^^rdf:JSON '7'^^rdf:JSON } ?a arrf:unnest ?x }", "x"))
						.containsExactly("1");
		assertThat(rows("SELECT ?s ?x WHERE { ?s ex:arr ?a . ?a arrf:unnest ?x } ORDER BY ?x", "s", "x"))
				.containsExactly("http://example.org/s1,1", "http://example.org/s1,2", "http://example.org/s2,3");
	}

	@Test
	void alreadyBoundObjectActsAsAFilter() {
		assertThat(rows("SELECT ?s ?x WHERE { VALUES ?x { 2 3 9 } ?s ex:arr ?a . ?a arrf:unnest ?x } ORDER BY ?x",
				"s", "x")).containsExactly("http://example.org/s1,2", "http://example.org/s2,3");
		// pins current behaviour: the filter is strict RDF term equality, so 2.0 does not match the element 2
		assertThat(rows("SELECT ?s WHERE { VALUES ?x { 2.0 '2'^^xsd:int } ?s ex:arr ?a . ?a arrf:unnest ?x }", "s"))
				.isEmpty();
		// both result variables of unnestWithOrdinality may be pre-bound
		assertThat(rows("SELECT ?s WHERE { VALUES (?x ?i) { (1 1) (2 1) } ?s ex:arr ?a ."
				+ " ?a arrf:unnestWithOrdinality (?x ?i) }", "s")).containsExactly("http://example.org/s1");
	}

	@Test
	void constantObjectActsAsAFilter() {
		assertThat(rows("SELECT ?s WHERE { ?s ex:arr ?a . ?a arrf:unnest 2 }", "s"))
				.containsExactly("http://example.org/s1");
		assertThat(rows("SELECT ?s WHERE { ?s ex:arr ?a . ?a arrf:unnest 3 }", "s"))
				.containsExactly("http://example.org/s2");
		assertThat(rows("SELECT ?s WHERE { ?s ex:arr ?a . ?a arrf:unnest 9 }", "s")).isEmpty();
		// pins current behaviour: strict term equality for constants too
		assertThat(rows("SELECT ?s WHERE { ?s ex:arr ?a . ?a arrf:unnest 2.0 }", "s")).isEmpty();
		// a constant in a result list position
		assertThat(rows("SELECT ?s ?i WHERE { ?s ex:arr ?a . ?a arrf:unnestWithOrdinality (2 ?i) }", "s", "i"))
				.containsExactly("http://example.org/s1,2");
		assertThat(rows("SELECT ?s ?x WHERE { ?s ex:arr ?a . ?a arrf:unnestWithOrdinality (?x 1) } ORDER BY ?s",
				"s", "x")).containsExactly("http://example.org/s1,1", "http://example.org/s2,3");
	}

	@Test
	void wrongLengthCollectionAndNilSubjectsYieldNoRows() {
		assertThat(rows("SELECT ?k ?n WHERE { VALUES ?k { 1 } (1) arrf:generateSeries ?n }", "k", "n")).isEmpty();
		assertThat(rows("SELECT ?k ?n WHERE { VALUES ?k { 1 } (1 2 3 4) arrf:generateSeries ?n }", "k", "n"))
				.isEmpty();
		assertThat(rows("SELECT ?k ?n WHERE { VALUES ?k { 1 } () arrf:generateSeries ?n }", "k", "n")).isEmpty();
		assertThat(rows("SELECT ?k ?x WHERE { VALUES ?k { 1 } () arrf:unnest ?x }", "k", "x")).isEmpty();
		assertThat(rows("SELECT ?k ?x WHERE { VALUES ?k { 1 } () arrf:unnestWithOrdinality (?x ?i) }", "k", "x"))
				.isEmpty();
		// the surrounding solution survives when the call is optional
		assertThat(rows("SELECT ?k ?n WHERE { VALUES ?k { 1 } OPTIONAL { (1) arrf:generateSeries ?n } }", "k", "n"))
				.containsExactly("1,UNBOUND");
		// and a well-formed collection next to it still works
		assertThat(rows("SELECT ?n WHERE { (1 2) arrf:generateSeries ?n } ORDER BY ?n", "n")).containsExactly("1", "2");
	}

	// ------------------------------------------------------------------ composition with other operators

	@Test
	void twoChainedMagicPropertiesExpandInDependencyOrder() {
		String expected = "[1,2],1|[1,2],2|[3],3";
		assertThat(rows("SELECT ?x ?y WHERE { VALUES ?a { '[[1,2],[3]]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x . ?x arrf:unnest ?y }", "x", "y")).containsExactly(expected.split("\\|"));
		// textual order of the two patterns does not matter: the consumer waits for its producer
		assertThat(rows("SELECT ?x ?y WHERE { VALUES ?a { '[[1,2],[3]]'^^rdf:JSON }"
				+ " ?x arrf:unnest ?y . ?a arrf:unnest ?x }", "x", "y")).containsExactly(expected.split("\\|"));
		// three levels, with ordinality on the innermost
		assertThat(rows("SELECT ?z ?i WHERE { VALUES ?a { '[[[\"p\",\"q\"]],[[\"r\"]]]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x . ?x arrf:unnest ?y . ?y arrf:unnestWithOrdinality (?z ?i) }", "z", "i"))
						.containsExactly("p,1", "q,2", "r,1");
		// an inner scalar element that is not an array contributes no inner rows but does not abort the rest
		assertThat(rows("SELECT ?y WHERE { VALUES ?a { '[[1],\"x\",[2]]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x . ?x arrf:unnest ?y } ORDER BY ?y", "y")).containsExactly("1", "2");
	}

	@Test
	void magicPropertyInsideOptional() {
		assertThat(rows("SELECT ?a ?x WHERE { VALUES ?a { '[1,2]'^^rdf:JSON '[]'^^rdf:JSON 'oops' }"
				+ " OPTIONAL { ?a arrf:unnest ?x } }", "a", "x"))
						.containsExactlyInAnyOrder("[1,2],1", "[1,2],2", "[],UNBOUND", "oops,UNBOUND");
		// OPTIONAL with a filter on the result
		assertThat(rows("SELECT ?s ?x WHERE { ?s ex:arr ?a OPTIONAL { ?a arrf:unnest ?x FILTER(?x > 2) } }"
				+ " ORDER BY ?s", "s", "x"))
						.containsExactly("http://example.org/s1,UNBOUND", "http://example.org/s2,3",
								"http://example.org/s4,UNBOUND");
	}

	@Test
	void magicPropertyInUnionBranches() {
		assertThat(rows("SELECT ?x ?i WHERE { { VALUES ?a { '[7,8]'^^rdf:JSON } ?a arrf:unnest ?x }"
				+ " UNION { VALUES ?a { '[7,8]'^^rdf:JSON } ?a arrf:unnestWithOrdinality (?x ?i) } }", "x", "i"))
						.containsExactlyInAnyOrder("7,UNBOUND", "8,UNBOUND", "7,1", "8,2");
		// data patterns in the branches bind the argument within the branch group
		assertThat(rows("SELECT ?s ?x WHERE { { ?s ex:arr ?a . ?a arrf:unnest ?x } UNION"
				+ " { ?s ex:name ?n . BIND(jsonf:jsonArray(?n) AS ?a) ?a arrf:unnest ?x } }", "s", "x"))
						.containsExactlyInAnyOrder("http://example.org/s1,1", "http://example.org/s1,2",
								"http://example.org/s1,one", "http://example.org/s2,3", "http://example.org/s2,two",
								"http://example.org/s3,three");
		// pins current behaviour: an argument bound only outside the UNION (a separate scope) is not visible to the
		// call inside a branch, so the branches contribute nothing (the doc requires the argument to be bound by the
		// group of the call)
		assertThat(rows("SELECT ?x ?i WHERE { VALUES ?a { '[7,8]'^^rdf:JSON }"
				+ " { ?a arrf:unnest ?x } UNION { ?a arrf:unnestWithOrdinality (?x ?i) } }", "x", "i")).isEmpty();
		// a branch whose argument is unbound contributes nothing while the other still does
		assertThat(rows("SELECT ?x WHERE { { ?b arrf:unnest ?x } UNION { VALUES ?a { '[7]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x } }", "x")).containsExactly("7");
	}

	@Test
	void magicPropertyWithMinus() {
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,2,3]'^^rdf:JSON } ?a arrf:unnest ?x"
				+ " MINUS { VALUES ?x { 2 } } } ORDER BY ?x", "x")).containsExactly("1", "3");
		assertThat(rows("SELECT ?x WHERE { VALUES ?x { 1 2 3 } MINUS { VALUES ?a { '[2]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x } } ORDER BY ?x", "x")).containsExactly("1", "3");
		// MINUS without shared variables removes nothing
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,2]'^^rdf:JSON } ?a arrf:unnest ?x"
				+ " MINUS { VALUES ?b { '[1,2]'^^rdf:JSON } ?b arrf:unnest ?y } } ORDER BY ?x", "x"))
						.containsExactly("1", "2");
	}

	@Test
	void magicPropertyInConstantGraphClauseIsNotRestrictedByTheGraph() {
		// the call does not read data, so an absent graph does not restrict a block made of magic patterns only (doc)
		assertThat(rows("SELECT ?n WHERE { GRAPH <urn:absent> { (1 2) arrf:generateSeries ?n } } ORDER BY ?n", "n"))
				.containsExactly("1", "2");
		assertThat(rows("SELECT ?x WHERE { GRAPH <urn:absent> { ex:s1 ex:arr ?a . ?a arrf:unnest ?x } }", "x"))
				.isEmpty();
		// pins current behaviour: once the block also holds non-pattern content (VALUES), the parser wraps it in a
		// Graph operator which applies the standard dataset semantics, so a graph absent from the store yields no rows
		assertThat(rows("SELECT ?x WHERE { GRAPH <urn:absent> { VALUES ?a { '[1,2]'^^rdf:JSON } ?a arrf:unnest ?x } }",
				"x")).isEmpty();
		// pins current behaviour: an argument bound outside the block is visible to the call inside, and the absent
		// graph does not restrict it either (with or without ORDER BY)
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,2]'^^rdf:JSON } GRAPH <urn:absent> { ?a arrf:unnest ?x } }",
				"x")).containsExactlyInAnyOrder("1", "2");
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,2]'^^rdf:JSON } GRAPH <urn:absent> { ?a arrf:unnest ?x } }"
				+ " ORDER BY ?x", "x")).containsExactly("1", "2");
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o"), VF.createIRI("urn:g1"));
			conn.add(VF.createIRI("urn:s"), EX_ARR, VF.createLiteral("[8,9]", CoreDatatype.RDF.JSON),
					VF.createIRI("urn:g1"));
		}
		assertThat(rows("SELECT ?x WHERE { GRAPH <urn:g1> { VALUES ?a { '[1,2]'^^rdf:JSON } ?a arrf:unnest ?x } }"
				+ " ORDER BY ?x", "x")).containsExactly("1", "2");
		// data patterns inside the same GRAPH block are still restricted to that graph
		assertThat(rows("SELECT ?x WHERE { GRAPH <urn:g1> { <urn:s> ex:arr ?a . ?a arrf:unnest ?x } } ORDER BY ?x",
				"x")).containsExactly("8", "9");
		assertThat(rows("SELECT ?x WHERE { GRAPH <urn:absent> { <urn:s> ex:arr ?a . ?a arrf:unnest ?x } }", "x"))
				.isEmpty();
		// the default-graph arrays are not visible inside the named graph
		assertThat(rows("SELECT ?x WHERE { GRAPH <urn:g1> { ex:s1 ex:arr ?a . ?a arrf:unnest ?x } }", "x"))
				.isEmpty();
		// pins current behaviour: an argument bound outside the GRAPH block is visible to the call inside, and once
		// the store holds any named graph the absent-graph form yields rows as well (unlike with no named graphs)
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,2]'^^rdf:JSON } GRAPH <urn:g1> { ?a arrf:unnest ?x } }"
				+ " ORDER BY ?x", "x")).containsExactly("1", "2");
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,2]'^^rdf:JSON } GRAPH <urn:absent> { ?a arrf:unnest ?x } }"
				+ " ORDER BY ?x", "x")).containsExactly("1", "2");
	}

	@Test
	void magicPropertyInVariableGraphClauseWithZeroNamedGraphsYieldsNoRows() {
		assertThat(rows("SELECT ?g ?x WHERE { GRAPH ?g { VALUES ?a { '[1,2]'^^rdf:JSON } ?a arrf:unnest ?x } }",
				"g", "x")).isEmpty();
		assertThat(rows("SELECT ?g ?n WHERE { GRAPH ?g { (1 2) arrf:generateSeries ?n } }", "g", "n")).isEmpty();
		// the same call outside GRAPH still produces rows, so the empty result is the graph iteration
		assertThat(rows("SELECT ?n WHERE { (1 2) arrf:generateSeries ?n } ORDER BY ?n", "n")).containsExactly("1", "2");
	}

	@Test
	void magicPropertyInVariableGraphClauseIsEvaluatedOncePerNamedGraph() {
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o"), VF.createIRI("urn:g1"));
			conn.add(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createIRI("urn:o2"), VF.createIRI("urn:g2"));
			conn.add(VF.createIRI("urn:s"), EX_ARR, VF.createLiteral("[7]", CoreDatatype.RDF.JSON),
					VF.createIRI("urn:g2"));
		}
		// a call with its argument bound inside the block runs once per named graph, binding ?g
		assertThat(rows("SELECT ?g ?x WHERE { GRAPH ?g { VALUES ?a { '[1,2]'^^rdf:JSON } ?a arrf:unnest ?x } }"
				+ " ORDER BY ?g ?x", "g", "x")).containsExactly("urn:g1,1", "urn:g1,2", "urn:g2,1", "urn:g2,2");
		assertThat(rows("SELECT ?g ?n WHERE { GRAPH ?g { (1 2) arrf:generateSeries ?n } } ORDER BY ?g ?n", "g", "n"))
				.containsExactly("urn:g1,1", "urn:g1,2", "urn:g2,1", "urn:g2,2");
		// combined with a data pattern in the graph, the call runs per matching solution of that graph only
		assertThat(rows("SELECT ?g ?x WHERE { GRAPH ?g { <urn:s> ex:arr ?a . ?a arrf:unnest ?x } }", "g", "x"))
				.containsExactly("urn:g2,7");
	}

	@Test
	void magicPropertyInsideSubSelectWithLimit() {
		assertThat(rows("SELECT ?x WHERE { { SELECT ?x WHERE { VALUES ?a { '[3,1,2]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x } ORDER BY ?x LIMIT 2 } } ORDER BY ?x", "x")).containsExactly("1", "2");
		assertThat(rows("SELECT ?x WHERE { { SELECT ?x WHERE { VALUES ?a { '[3,1,2]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x } ORDER BY DESC(?x) LIMIT 1 OFFSET 1 } }", "x")).containsExactly("2");
		// the sub-select is a scope: an argument bound only outside of it is not visible inside
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[3,1,2]'^^rdf:JSON }"
				+ " { SELECT ?x WHERE { ?a arrf:unnest ?x } LIMIT 5 } }", "x")).isEmpty();
		// projecting the argument out of the sub-select joins it with the outer binding
		assertThat(rows("SELECT ?x WHERE { ?s ex:arr ?a { SELECT ?a ?x WHERE { ?s ex:arr ?a . ?a arrf:unnest ?x }"
				+ " ORDER BY ?x LIMIT 2 } } ORDER BY ?x", "x")).containsExactly("1", "2");
	}

	@Test
	void argumentLeftUnboundByAnOptionalYieldsNoRowsForThatSolution() {
		assertThat(rows("SELECT ?s ?x WHERE { VALUES ?s { ex:s1 ex:s3 } OPTIONAL { ?s ex:arr ?a }"
				+ " ?a arrf:unnest ?x } ORDER BY ?s ?x", "s", "x"))
						.containsExactly("http://example.org/s1,1", "http://example.org/s1,2");
		// wrapping the call in OPTIONAL keeps the solution with an unbound result
		assertThat(rows("SELECT ?s ?x WHERE { VALUES ?s { ex:s1 ex:s3 } OPTIONAL { ?s ex:arr ?a }"
				+ " OPTIONAL { ?a arrf:unnest ?x } } ORDER BY ?s ?x", "s", "x"))
						.containsExactly("http://example.org/s1,1", "http://example.org/s1,2",
								"http://example.org/s3,UNBOUND");
	}

	@Test
	void bindAndFilterAfterTheMagicPropertyInTheSameGroup() {
		assertThat(rows("SELECT ?x ?y WHERE { VALUES ?a { '[1,2,3]'^^rdf:JSON } ?a arrf:unnest ?x"
				+ " BIND(?x * 10 AS ?y) FILTER(?x > 1) } ORDER BY ?x", "x", "y")).containsExactly("2,20", "3,30");
		// a FILTER placed before the pattern applies to the whole group as usual
		assertThat(rows("SELECT ?x ?y WHERE { VALUES ?a { '[1,2,3]'^^rdf:JSON } FILTER(?y = 30)"
				+ " ?a arrf:unnest ?x BIND(?x * 10 AS ?y) }", "x", "y")).containsExactly("3,30");
		// BIND output feeding a second magic property
		assertThat(rows("SELECT ?x ?n WHERE { VALUES ?a { '[2,3]'^^rdf:JSON } ?a arrf:unnest ?x"
				+ " BIND(?x - 1 AS ?from) (?from ?x) arrf:generateSeries ?n } ORDER BY ?x ?n", "x", "n"))
						.containsExactly("2,1", "2,2", "3,2", "3,3");
		// scalar JSON functions over the unnested element
		assertThat(rows("SELECT ?x ?k WHERE { VALUES ?a { '[{\"k\":\"a\"},{\"k\":\"b\"}]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x BIND(jsonf:jsonValue(?x, \"$.k\") AS ?k) } ORDER BY ?k", "k"))
						.containsExactly("a", "b");
	}

	// ------------------------------------------------------------------ unnest / unnestWithOrdinality semantics

	@Test
	void unnestWithOrdinalityIsOneBasedIntegerAndYieldsValueKeyPairsForObjects() {
		List<BindingSet> result = evaluate("SELECT ?v ?i WHERE { VALUES ?a { '[\"a\",\"b\",\"c\"]'^^rdf:JSON }"
				+ " ?a arrf:unnestWithOrdinality (?v ?i) } ORDER BY ?i");
		assertThat(result).extracting(row -> row.getValue("v").stringValue() + "," + row.getValue("i").stringValue())
				.containsExactly("a,1", "b,2", "c,3");
		for (BindingSet row : result) {
			Literal index = (Literal) row.getValue("i");
			assertThat(index.getCoreDatatype()).isEqualTo(CoreDatatype.XSD.INTEGER);
		}
		assertThat(rows("SELECT ?v ?k WHERE { VALUES ?a { '{\"k\":1,\"m\":\"v\",\"n\":null}'^^rdf:JSON }"
				+ " ?a arrf:unnestWithOrdinality (?v ?k) }", "v", "k")).containsExactly("1,k", "v,m");
		assertThat(rows("SELECT ?v ?i WHERE { VALUES ?a { '[]'^^rdf:JSON '{}'^^rdf:JSON }"
				+ " ?a arrf:unnestWithOrdinality (?v ?i) }", "v", "i")).isEmpty();
		// pins current behaviour: null elements are skipped but keep their position in the numbering
		assertThat(rows("SELECT ?v ?i WHERE { VALUES ?a { '[null,\"x\",null,\"y\"]'^^rdf:JSON }"
				+ " ?a arrf:unnestWithOrdinality (?v ?i) } ORDER BY ?i", "v", "i")).containsExactly("x,2", "y,4");
		// the object key is a plain string literal
		List<BindingSet> keys = evaluate("SELECT ?k WHERE { VALUES ?a { '{\"k\":1}'^^rdf:JSON }"
				+ " ?a arrf:unnestWithOrdinality (?v ?k) }");
		assertThat(keys).hasSize(1);
		assertThat(((Literal) keys.get(0).getValue("k")).getCoreDatatype()).isEqualTo(CoreDatatype.XSD.STRING);
	}

	@Test
	void unnestOnObjectYieldsMemberValuesAndOnScalarYieldsNoRows() {
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '{\"k\":1,\"m\":\"v\",\"n\":null,\"o\":{\"p\":2}}'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x }", "x")).containsExactly("1", "v", "{\"p\":2}");
		// pins current behaviour: a scalar JSON document contributes zero rows (the function rejects it)
		assertThat(rows("SELECT ?a ?x WHERE { VALUES ?a { '5'^^rdf:JSON '\"s\"'^^rdf:JSON 'true'^^rdf:JSON"
				+ " 'null'^^rdf:JSON } ?a arrf:unnest ?x }", "a", "x")).isEmpty();
		// null members are skipped, so an all-null array gives no rows while the solution itself is kept by OPTIONAL
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[null,null]'^^rdf:JSON } OPTIONAL { ?a arrf:unnest ?x } }",
				"x")).containsExactly("UNBOUND");
	}

	@Test
	void elementEncodingsDecodeBackToRdfTerms() {
		List<BindingSet> result = evaluate("SELECT ?x WHERE { VALUES ?a { '[{\"@id\":\"urn:x\"},"
				+ "{\"@value\":\"1\",\"@type\":\"http://www.w3.org/2001/XMLSchema#byte\"},"
				+ "{\"@value\":\"hi\",\"@language\":\"en\"},true,2.5,{\"@id\":\"_:b1\"},\"s\",[1],{\"k\":1}]'"
				+ "^^rdf:JSON }"
				+ " ?a arrf:unnest ?x }");
		assertThat(result).hasSize(9);
		List<Value> values = result.stream().map(row -> row.getValue("x")).toList();
		assertThat(values.get(0)).isEqualTo(VF.createIRI("urn:x"));
		assertThat(values.get(1)).isEqualTo(VF.createLiteral("1", XSD.BYTE));
		assertThat(values.get(2)).isEqualTo(VF.createLiteral("hi", "en"));
		assertThat(values.get(3)).isEqualTo(VF.createLiteral(true));
		assertThat(values.get(4)).isEqualTo(VF.createLiteral(new java.math.BigDecimal("2.5")));
		assertThat(values.get(5).isBNode()).isTrue();
		assertThat(values.get(6)).isEqualTo(VF.createLiteral("s"));
		assertThat(values.get(7)).isEqualTo(VF.createLiteral("[1]", CoreDatatype.RDF.JSON));
		assertThat(values.get(8)).isEqualTo(VF.createLiteral("{\"k\":1}", CoreDatatype.RDF.JSON));
		// pins current behaviour: elements are decoded eagerly, so one undecodable element (a huge exponent number or
		// a malformed term object) drops the whole solution rather than producing an error row
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,1e400,2]'^^rdf:JSON } ?a arrf:unnest ?x }", "x"))
				.isEmpty();
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,{\"@id\":\"not an iri\"},2]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x }", "x")).isEmpty();
		// a solution with a decodable array next to it is unaffected
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[1,1e400,2]'^^rdf:JSON '[9]'^^rdf:JSON }"
				+ " ?a arrf:unnest ?x }", "x")).containsExactly("9");
		// huge exponent numbers are fine as long as they stay JSON
		assertThat(rows("SELECT ?x WHERE { VALUES ?a { '[[1e400]]'^^rdf:JSON } ?a arrf:unnest ?x }", "x"))
				.containsExactly("[1E+400]");
	}

	// ------------------------------------------------------------------ data bypass, optimizer and explain

	@Test
	void storedTripleWithTheMagicPredicateIsBypassed() {
		IRI s9 = VF.createIRI("http://example.org/s9");
		IRI o9 = VF.createIRI("http://example.org/o9");
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(s9, VF.createIRI(UNNEST), o9);
			conn.add(s9, VF.createIRI(UNNEST), VF.createLiteral("[5]", CoreDatatype.RDF.JSON));
			conn.add(s9, EX_ARR, VF.createLiteral("[6]", CoreDatatype.RDF.JSON));
		}
		// the pattern is a function call, never a data lookup: an unbound subject matches nothing
		assertThat(rows("SELECT ?s ?o WHERE { ?s arrf:unnest ?o }", "s", "o")).isEmpty();
		// a constant IRI subject is an argument the function rejects, so the stored objects are not returned
		assertThat(rows("SELECT ?o WHERE { ex:s9 arrf:unnest ?o }", "o")).isEmpty();
		// the stored triples are nevertheless in the data
		assertThat(rows("SELECT ?o WHERE { ex:s9 ?p ?o FILTER(?p = arrf:unnest) } ORDER BY ?o", "o"))
				.containsExactly("http://example.org/o9", "[5]");
		assertThat(rows("SELECT ?p ?o WHERE { ex:s9 ?p ?o } ORDER BY ?p ?o", "p", "o")).hasSize(3);
		// and the function path still works on the array stored under an ordinary predicate
		assertThat(rows("SELECT ?x WHERE { ex:s9 ex:arr ?a . ?a arrf:unnest ?x }", "x")).containsExactly("6");
	}

	@Test
	void optimizerLeavesOrdinaryPatternsUntouched() {
		String query = "SELECT ?s ?n ?x WHERE { ?s ex:arr ?a . ?a arrf:unnest ?x . ?s ex:name ?n } ORDER BY ?s ?x";
		assertThat(rows(query, "s", "n", "x")).containsExactly("http://example.org/s1,one,1",
				"http://example.org/s1,one,2", "http://example.org/s2,two,3");
		String unoptimized = explain(query, Explanation.Level.Unoptimized);
		assertThat(count(unoptimized, "StatementPattern")).isEqualTo(3);
		assertThat(unoptimized).doesNotContain("TupleFunctionCall");
		String optimized = explain(query, Explanation.Level.Optimized);
		// the two data patterns survive as statement patterns, the magic pattern alone became a call
		assertThat(count(optimized, "StatementPattern")).isEqualTo(2);
		assertThat(optimized).contains("http://example.org/arr").contains("http://example.org/name");
		assertThat(count(optimized, UNNEST)).isEqualTo(1);
		assertThat(optimized).contains("TupleFunctionCall (" + UNNEST + ")");
		// a query without magic properties is not rewritten at all
		String plain = explain("SELECT ?s ?n WHERE { ?s ex:arr ?a . ?s ex:name ?n }", Explanation.Level.Optimized);
		assertThat(plain).doesNotContain("TupleFunctionCall").doesNotContain("Lateral");
		assertThat(count(plain, "StatementPattern")).isEqualTo(2);
	}

	@Test
	void explainRendersTheTupleFunctionCallNode() {
		String query = "SELECT ?x ?i WHERE { ?s ex:arr ?a . ?a arrf:unnestWithOrdinality (?x ?i) }";
		String optimized = explain(query, Explanation.Level.Optimized);
		assertThat(optimized).contains("TupleFunctionCall (http://rdf4j.org/function/array#unnestWithOrdinality)");
		// the result variables and the argument variable are part of the rendered node
		assertThat(optimized).contains("name=x").contains("name=i").contains("name=a");
		// the executed plan renders the same node after actually running the query
		String executed = explain(query, Explanation.Level.Executed);
		assertThat(executed).contains("TupleFunctionCall (http://rdf4j.org/function/array#unnestWithOrdinality)");
		// generateSeries with constant arguments renders its constants
		String series = explain("SELECT ?n WHERE { (1 3) arrf:generateSeries ?n }", Explanation.Level.Optimized);
		assertThat(series).contains("TupleFunctionCall (http://rdf4j.org/function/array#generateSeries)")
				.contains("ValueConstant")
				.doesNotContain("rdf-syntax-ns#first");
	}

	// ------------------------------------------------------------------ scalar family at SPARQL level

	@Test
	void scalarJsonAndArrayFunctionsWorkInEveryClausePosition() {
		// FILTER and SELECT expression
		assertThat(rows("SELECT ?s (jsonf:jsonValue(?a, \"$[0]\") AS ?first) WHERE { ?s ex:arr ?a"
				+ " FILTER(jsonf:jsonExists(?a, \"$[1]\")) }", "s", "first"))
						.containsExactly("http://example.org/s1,1");
		// BIND and ORDER BY (s4 holds a scalar document and is excluded by the filter)
		assertThat(rows("SELECT ?s ?n WHERE { ?s ex:arr ?a FILTER(jsonf:jsonExists(?a, \"$[0]\"))"
				+ " BIND(arrf:arrayLength(?a) AS ?n) } ORDER BY arrf:arrayLength(?a)", "s", "n"))
						.containsExactly("http://example.org/s2,1", "http://example.org/s1,2");
		assertThat(rows("SELECT ?s WHERE { ?s ex:arr ?a FILTER(jsonf:jsonExists(?a, \"$[0]\")) }"
				+ " ORDER BY DESC(jsonf:jsonArrayLength(?a))", "s"))
						.containsExactly("http://example.org/s1", "http://example.org/s2");
		// GROUP BY key
		assertThat(rows("SELECT ?len (COUNT(?s) AS ?c) WHERE { ?s ex:arr ?a FILTER(jsonf:jsonExists(?a, \"$[0]\")) }"
				+ " GROUP BY (arrf:arrayLength(?a) AS ?len) ORDER BY ?len", "len", "c")).containsExactly("1,1", "2,1");
		// sub-select
		assertThat(rows("SELECT ?m WHERE { { SELECT (MAX(arrf:arrayLength(?a)) AS ?m) WHERE { ?s ex:arr ?a"
				+ " FILTER(jsonf:jsonExists(?a, \"$[0]\")) } } }", "m")).containsExactly("2");
		// constructors, set and contains composed in one expression
		assertThat(rows("SELECT ?r WHERE { BIND(arrf:arrayContains("
				+ "jsonf:jsonSet(jsonf:jsonArray(1, 2), \"$[2]\", 3), 3) AS ?r) }", "r")).containsExactly("true");
		assertThat(rows("SELECT ?r WHERE { BIND(jsonf:jsonKeys(jsonf:jsonObject(\"b\", 1, \"a\", 2)) AS ?r) }", "r"))
				.containsExactly("[\"b\",\"a\"]");
		assertThat(rows("SELECT ?r WHERE { BIND(jsonf:jsonQuery(arrf:generateSeries(1, 3), \"$[-1]\") AS ?r) }", "r"))
				.containsExactly("3");
	}

	@Test
	void unboundOrRejectedScalarArgumentLeavesBindUnboundAndTheQueryContinues() {
		assertThat(rows("SELECT ?s ?n ?v WHERE { VALUES ?s { ex:s1 ex:s3 ex:s4 } OPTIONAL { ?s ex:arr ?a }"
				+ " BIND(arrf:arrayLength(?a) AS ?n) BIND(jsonf:jsonValue(?a, \"$[0]\") AS ?v) } ORDER BY ?s", "s",
				"n", "v")).containsExactly("http://example.org/s1,2,1", "http://example.org/s3,UNBOUND,UNBOUND",
						"http://example.org/s4,UNBOUND,UNBOUND");
		// in FILTER an error is false, so only the solution with a usable array survives
		assertThat(rows("SELECT ?s WHERE { VALUES ?s { ex:s1 ex:s3 ex:s4 } OPTIONAL { ?s ex:arr ?a }"
				+ " FILTER(arrf:arrayContains(?a, 1)) }", "s")).containsExactly("http://example.org/s1");
		assertThat(rows("SELECT ?s WHERE { VALUES ?s { ex:s1 ex:s3 ex:s4 } OPTIONAL { ?s ex:arr ?a }"
				+ " FILTER(!arrf:arrayContains(?a, 1)) }", "s")).isEmpty();
		// wrong arity at the SPARQL level is also an evaluation error, not a query failure
		assertThat(rows("SELECT ?s ?r WHERE { ?s ex:name ?n BIND(jsonf:jsonValue(\"[1]\") AS ?r) } ORDER BY ?s", "r"))
				.containsExactly("UNBOUND", "UNBOUND", "UNBOUND");
		assertThat(rows("SELECT ?r WHERE { BIND(arrf:generateSeries(1, 2, 3, 4) AS ?r) }", "r"))
				.containsExactly("UNBOUND");
	}
}
